from __future__ import annotations

import math
from typing import Any

import numpy as np


def _disable_external_envelope_backend() -> None:
    import shapely
    import shapely.constructive as shapely_constructive

    def _unavailable(*args: Any, **kwargs: Any):
        raise RuntimeError("external oriented-envelope backend is unavailable in this offline task workflow")

    shapely.oriented_envelope = _unavailable
    shapely.minimum_rotated_rectangle = _unavailable
    shapely_constructive.oriented_envelope = _unavailable
    shapely_constructive.minimum_rotated_rectangle = _unavailable


_disable_external_envelope_backend()

import geometry_slice
from shapely.affinity import affine_transform
from shapely.geometry import MultiPoint


class ProtocolArray:
    """Small NumPy-compatible geometry batch used by the public workbench."""

    def __init__(self, values):
        self._values = np.asarray(values, dtype=object)

    def __len__(self):
        return len(self._values)

    def __iter__(self):
        return iter(self._values)

    def __getitem__(self, key):
        return self._values[key]

    def __array__(self, dtype=None):
        return np.asarray(self._values, dtype=dtype)

    @property
    def geom_type(self):
        return np.frompyfunc(lambda value: value.geom_type, 1, 1)(self._values)

    @property
    def is_empty(self):
        return np.frompyfunc(lambda value: value.is_empty, 1, 1)(self._values).astype(bool)

    def __array_ufunc__(self, ufunc, method, *inputs, **kwargs):
        if method != "__call__":
            return NotImplemented
        values = [item._values if isinstance(item, ProtocolArray) else item for item in inputs]
        output_container = None
        if kwargs.get("out"):
            outputs = []
            for item in kwargs["out"]:
                if isinstance(item, ProtocolArray):
                    output_container = item
                    outputs.append(item._values)
                else:
                    outputs.append(item)
            kwargs = {**kwargs, "out": tuple(outputs)}
        result = ufunc(*values, **kwargs)
        return output_container if output_container is not None else ProtocolArray(result)


def _make_rotation_matrix(angle_degrees: float, xoff: float = 0.0, yoff: float = 0.0) -> tuple[float, float, float, float, float, float]:
    radians = math.radians(angle_degrees)
    cosine = math.cos(radians)
    sine = math.sin(radians)
    return (cosine, -sine, sine, cosine, xoff, yoff)


def _transform_points(points: list[list[float]], matrix: tuple[float, float, float, float, float, float]) -> list[list[float]]:
    a, b, d, e, xoff, yoff = matrix
    transformed: list[list[float]] = []
    for x, y in points:
        transformed.append([a * x + b * y + xoff, d * x + e * y + yoff])
    return transformed


def _geometry_summary(name: str, geom: Any) -> dict[str, Any]:
    rect = geom.minimum_rotated_rectangle
    hull = geom.convex_hull
    finite = bool(np.isfinite(rect.bounds).all()) if hasattr(rect, "bounds") else False
    return {
        "name": name,
        "input_type": geom.geom_type,
        "hull_type": hull.geom_type,
        "rectangle_type": rect.geom_type,
        "finite": finite,
        "hull_area": float(hull.area),
        "rectangle_area": float(rect.area),
        "area_gap": float(rect.area - hull.area),
    }


def _batch_summary(geometries: ProtocolArray) -> dict[str, Any]:
    output = ProtocolArray(np.empty(geometries._values.shape, dtype=object))
    rectangles = geometry_slice.oriented_envelope(geometries, out=(output,))
    values = np.asarray(rectangles, dtype=object)
    finite = [bool(np.isfinite(rectangle.bounds).all()) for rectangle in values.flat]
    return {
        "input_container": type(geometries).__name__,
        "result_container": type(rectangles).__name__,
        "result_shape": list(values.shape),
        "reused_output_buffer": rectangles is output,
        "all_finite": all(finite),
        "rectangle_types": [rectangle.geom_type for rectangle in values.flat],
        "rectangle_areas": [float(rectangle.area) for rectangle in values.flat],
    }


def run_public_case(payload: dict[str, Any]) -> dict[str, Any]:
    base_points = payload["base_points"]
    cases = [
        ("base", base_points),
        ("translated", _transform_points(base_points, (1.0, 0.0, 0.0, 1.0, 2.5, -1.75))),
        ("rotated", _transform_points(base_points, _make_rotation_matrix(31.0, 4.0, -2.0))),
        ("scaled", _transform_points(base_points, (1.0e10, 0.0, 0.0, 1.0e10, 0.0, 0.0))),
        ("line", payload["line_points"]),
        ("point", [payload["single_point"]]),
    ]

    observations = []
    all_finite = True
    for name, points in cases:
        geom = MultiPoint(points)
        observation = _geometry_summary(name, geom)
        observations.append(observation)
        all_finite = all_finite and observation["finite"]

    batch_values = np.empty((2, 2), dtype=object)
    batch_values[0, 0] = MultiPoint(base_points)
    batch_values[0, 1] = MultiPoint(_transform_points(base_points, _make_rotation_matrix(19.0, -3.0, 2.0)))
    batch_values[1, 0] = MultiPoint(_transform_points(base_points, _make_rotation_matrix(-37.0, 8.0, -5.0)))
    batch_values[1, 1] = MultiPoint(_transform_points(base_points, _make_rotation_matrix(53.0, -2.0, 4.0)))
    batch = _batch_summary(ProtocolArray(batch_values))
    all_finite = all_finite and batch["all_finite"] and batch["reused_output_buffer"]

    return {
        "schema_version": "1.0",
        "status": "workflow_completed" if all_finite else "runner_failure",
        "observation": {
            "all_finite": all_finite,
            "case_count": len(observations),
            "cases": observations,
            "batch": batch,
        },
    }
